"""Small, testable helpers for reconciling dates affected by an activity edit."""

import datetime
import json
import math
import os
import re
import tempfile
import xml.etree.ElementTree as ET
from pathlib import Path


DATED_TCX = re.compile(
    r"(?P<year>\d{4})_(?P<month>\d{2})_(?P<day>\d{2})_(?P<id>[1-9]\d*)\.tcx"
)
UNDATED_TCX = re.compile(r"(?P<id>[1-9]\d*)\.tcx")


def activity_id(filename: str) -> int | None:
    """Return the result ID only for filenames generated by the backup scripts."""
    match = DATED_TCX.fullmatch(filename) or UNDATED_TCX.fullmatch(filename)
    return int(match.group("id")) if match else None


def activity_date(filename: str) -> str | None:
    """Read the calendar date from a standard dated TCX filename."""
    match = DATED_TCX.fullmatch(filename)
    if not match:
        return None
    try:
        return datetime.date(
            int(match.group("year")), int(match.group("month")), int(match.group("day"))
        ).isoformat()
    except ValueError:
        return None


def tcx_distance(content: bytes) -> int:
    """Validate a downloaded TCX and return its summed lap distance."""
    try:
        root = ET.fromstring(content)
    except ET.ParseError as exc:
        raise ValueError("Invalid TCX XML") from exc
    if root.tag.rsplit("}", 1)[-1] != "TrainingCenterDatabase":
        raise ValueError("Not a TrainingCenterDatabase document")

    distances = []
    for lap in root.iter():
        if lap.tag.rsplit("}", 1)[-1] != "Lap":
            continue
        for child in lap:
            if child.tag.rsplit("}", 1)[-1] == "DistanceMeters":
                try:
                    value = float(child.text)
                except (TypeError, ValueError) as exc:
                    raise ValueError("Invalid TCX lap distance") from exc
                if not math.isfinite(value) or value < 0:
                    raise ValueError("Invalid TCX lap distance")
                distances.append(value)
    if not distances:
        raise ValueError("TCX has no lap distance")
    return int(sum(distances))


def write_atomically(path: Path, content: bytes) -> None:
    """Replace one file only after the complete content is present beside it."""
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(
            dir=path.parent, prefix=f".{path.name}.", delete=False
        ) as handle:
            temporary = Path(handle.name)
            handle.write(content)
        os.replace(temporary, path)
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)


def refresh_dates(data_dir: Path, dates: set[str]) -> None:
    """Rebuild only edited dates from current TCX files, preserving other history."""
    if not dates:
        return

    stats_file = data_dir / "stats.json"
    if stats_file.exists():
        with stats_file.open(encoding="utf-8") as handle:
            stats = json.load(handle)
    else:
        stats = {"processed_files": [], "daily_distances": {}}

    current = {date: [] for date in dates}
    for path in data_dir.rglob("*.tcx"):
        date = activity_date(path.name)
        if date in current:
            current[date].append(path)

    daily_distances = stats.setdefault("daily_distances", {})
    for date, paths in current.items():
        if paths:
            daily_distances[date] = sum(
                tcx_distance(path.read_bytes()) for path in paths
            )
        else:
            daily_distances.pop(date, None)

    unaffected = [
        filename
        for filename in stats.get("processed_files", [])
        if activity_date(filename) not in dates
    ]
    affected = [path.name for paths in current.values() for path in sorted(paths)]
    stats["processed_files"] = list(dict.fromkeys(unaffected + sorted(affected)))
    write_atomically(
        stats_file, (json.dumps(stats, indent=2, sort_keys=True) + "\n").encode("utf-8")
    )
